import sys

data = sys.stdin.read().split()
n, m = int(data[0]), int(data[1])
s1, s2, t = int(data[2]), int(data[3]), int(data[4])
edges = []
pos = 5
for _ in range(m):
    edges.append((int(data[pos]), int(data[pos + 1]), int(data[pos + 2])))
    pos += 3

def reaches(chosen, s):
    seen = {s}
    stack = [s]
    while stack:
        u = stack.pop()
        for i in chosen:
            a, b, _ = edges[i]
            if a == u and b not in seen:
                seen.add(b)
                stack.append(b)
    return t in seen

best = -1
for mask in range(1 << m):
    chosen = [i for i in range(m) if mask >> i & 1]
    cost = sum(edges[i][2] for i in chosen)
    if best != -1 and cost >= best:
        continue
    if reaches(chosen, s1) and reaches(chosen, s2):
        best = cost
print(best)

